# Keep prose adjacent to mathematical quantities legible without altering atomic labels.
def readable(v):
 if isinstance(v,str):
  v=re.sub(r'\b([A-Za-z]{3,}|at|is|to|in|by|of|as|on)(?=[0-9ℓμλθΔ√−±ℏ])',r'\1 ',v)
  v=re.sub(r'(?<=[0-9])(?=(?:states|electrons|closed|whole|would|atoms|times|keV|eV|GHz|MHz|Hz|years)\b)', ' ',v)
  return v
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:(x if k=='id' else readable(x)) for k,x in v.items()}
 return v
